/* V7 actual-browser integration. Explicit fixture groups arrange rare states;
 * natural DOM runs do not edit HP, gold, cards, routes, XP, levels or weapons. */
'use strict';
const fs=require('node:fs'),path=require('node:path'),http=require('node:http'),crypto=require('node:crypto'),assert=require('node:assert/strict');
const {chromium}=require('playwright');
const target=path.resolve(process.argv[2]||path.join(__dirname,'..','index.html'));
const inlineTarget=path.resolve(process.argv[3]||path.join(path.dirname(target),'baiyao-standalone.html'));
const hash=x=>crypto.createHash('sha256').update(x).digest('hex');
const report={format:'baiyao-v7-browser',target,inlineTarget,results:[],errors:[],externalRequests:[],localRequests:[],expectedMissingRequests:[]};
let browser,page,server,origin;
const state=()=>page.evaluate(()=>JSON.parse(JSON.stringify(game.state)));
const idle=()=>page.waitForFunction(()=>!window.uiBusy,null,{timeout:18000});
async function click(action,filter=''){await idle();await page.locator(`[data-action="${action}"]${filter}:not(:disabled)`).first().click({timeout:7000});}
async function newRun(starter='sword'){await idle();const ok=await page.evaluate(starter=>{const ok=game.newRun(starter);renderGame();setMotionMode('fast');return ok;},starter);assert.equal(ok,true,'newRun '+starter);}
async function enterRegion(){if((await state()).screen==='arrival')await click('arrival-enter');}
async function screenshot(name){fs.mkdirSync('/workspace/scratch',{recursive:true});await page.screenshot({path:`/workspace/scratch/v7-${name}.png`,fullPage:true});}
function watch(p){p.on('pageerror',e=>report.errors.push(e.message));p.on('request',r=>{const u=r.url();if(/^https?:/.test(u)){if(u.startsWith(origin+'/'))report.localRequests.push(u.slice(origin.length));else report.externalRequests.push(u);}});}
async function test(name,fn){if(process.env.QA_FILTER&&!process.env.QA_FILTER.split('|').some(x=>name.includes(x)))return;try{await fn();report.results.push({name,ok:true});console.log('PASS '+name);}catch(e){report.results.push({name,ok:false,error:e.stack});console.error('FAIL '+name+': '+e.message);}finally{await idle().catch(()=>{});await page.evaluate(()=>{document.querySelector('#modal-root [data-action="close"]')?.click();setMotionMode('fast');}).catch(()=>{});}}
async function play(id){await click('card',`[data-id="${id}"]`);if(await page.evaluate(id=>NightPact.CARDS[id].target,id))await click('target');await idle();}
async function endTurn(){await click('end-turn');await idle();}
const values={S03:10,S04:10,S05:8,S06:9,S07:10,S08:8,S09:9,S10:9,S11:10,S12:10,S13:10,S14:10,S15:10,S16:11,C16:9,C17:10,C18:10,C24:10,C28:12,C33:10,C34:9,C36:11};
async function reward(){let s=await state();if(s.reward.relicPending){const pref=['moonheart','dream','ninelives','godblood','vial','jade','moon','mirror','silk','fang','bloodstone'];const id=[...s.reward.relicChoices].sort((a,b)=>pref.indexOf(a)-pref.indexOf(b))[0];await click('choose-relic',`[data-relic="${id}"]`);s=await state();}const id=[...s.reward.cards].sort((a,b)=>(values[b]||6)-(values[a]||6))[0];await click('reward',`[data-id="${id}"]`);}
function chooseCard(s){
 const original=require('./playtest.cjs').nextCard;if(s.character!=='sovereign')return original(s);
 const b=s.battle,e=b.enemy,p=s.player,{CARDS:defs,ENEMIES}=require('./engine.js'),soul=b.soul||0,power=p.power||0;
 const hits=ENEMIES[e.id].intents[e.intentIndex].hits||[],incoming=hits.reduce((a,n)=>a+Math.max(0,n-(e.chill||0)),0),need=Math.max(0,incoming-b.block);
 let best=null;for(const card of b.hand){const c=defs[card.id],id=card.id;if(c.cost>b.energy)continue;
  const raw={F01:6+power,F04:10+3*soul+power,F05:9+power,F09:5+power,F10:16+power,F12:18+4*soul+power}[id]||0;
  let score=raw/Math.max(1,c.cost);if(raw>=e.hp+e.block&&raw)score+=180;
  const shield={F02:6,F06:3,F07:8}[id]||0;score+=Math.min(shield,need)*(p.hp<30?2.3:1.4)/Math.max(1,c.cost);
  if(id==='F01')score+=soul<6?4:0;if(id==='F03')score+=soul<5?28:soul===5?12:-40;
  if((id==='F04'||id==='F12')&&soul<3&&raw<e.hp+e.block)score-=5;
  if(id==='F06')score+=b.draw.length+b.discard.length>0?20:4;
  if(id==='F07'&&soul>=3)score+=b.energy>1?9:2;
  if(id==='F08')score+=b.energy>1?16:1;
  if(id==='F09')score+=Math.min(2,p.maxHp-p.hp)*3;
  if(id==='F10'&&power>=2)score+=b.energy>2?7:2;
  if(id==='F11')score+=soul>=2&&b.hand.some(x=>x!==card&&defs[x.id].cost>0)?27:-60;
  if(!best||score>best.score)best={card,score};
 }return best&&best.score>0?best.card:null;
}
async function autoBattle(){for(let i=0;i<600;i++){const s=await state();if(s.screen!=='battle')return s.screen;const c=chooseCard(s);if(c)await play(c.id);else await endTurn();}throw Error('Battle did not terminate');}
// Fixture only: bypass intervening rooms while retaining public advancement.
async function skipToFloor(floor){await page.evaluate(floor=>{let i=0;while(game.state.floor<floor){if(++i>50)throw Error('fixture skip stalled');const s=game.state;if(s.screen==='arrival'){game.enterRegion();continue;}if(s.screen!=='map')throw Error('fixture expected map, got '+s.screen);const n=game.getAvailableNodes()[0];n.type='rest';delete n.storyId;game.enterNode(n.id);game.rest(false);}renderGame();setMotionMode('fast');},floor);}
async function eventFixture(id,{floor=1,hp=60,gold=300,starter='sword'}={}){await newRun(starter);await enterRegion();await skipToFloor(floor);await enterRegion();await page.evaluate(({id,hp,gold})=>{const s=game.state,n=game.getAvailableNodes()[0];n.type='event';n.storyId=id;s.player.hp=hp;s.player.gold=gold;game.enterNode(n.id);renderGame();}, {id,hp,gold});assert.equal((await state()).event.id,id);}
async function chooseOnce(index){await click('event-choice',`[data-index="${index}"]`);const after=await state();assert.equal(after.event.resolved,true);const snapshot=JSON.stringify({player:after.player,journey:after.journey});assert.equal(await page.evaluate(index=>game.chooseEvent(index),index),false);assert.equal(JSON.stringify({player:(await state()).player,journey:(await state()).journey}),snapshot);return after;}
async function fixtureKill(){await page.evaluate(()=>{const s=game.state,b=s.battle,id=s.character==='sword'?'S01':s.character==='sovereign'?'F01':'C01';b.enemy.hp=1;b.enemy.block=0;b.energy=10;b.hand=[{id,uid:'v7-fixture-kill'}];b.phase='player';renderGame();});await play((await state()).character==='sword'?'S01':(await state()).character==='sovereign'?'F01':'C01');}
async function battleFixture(floor=1,options={}){await newRun(options.starter||'sword');await enterRegion();await skipToFloor(floor);await enterRegion();await page.evaluate(options=>{const s=game.state,n=game.getAvailableNodes()[0];n.type=options.kind||'fight';delete n.storyId;Object.assign(s.player,options.player||{});game.enterNode(n.id);if(options.enemy){const d=NightPact.ENEMIES[options.enemy];Object.assign(s.battle.enemy,{id:options.enemy,name:d.name,hp:d.hp,maxHp:d.hp,intentIndex:0});}renderGame();},options);assert.equal((await state()).screen,'battle');}
async function naturalRun(starter){
 const attempts=[];for(let attempt=0;attempt<6;attempt++){
  await page.goto(origin+'/'+path.basename(target),{waitUntil:'load'});await page.waitForFunction(()=>window.game);const who=starter==='sword'?'sword':starter==='sovereign'?'sovereign':'assassin';await click('character',`[data-character="${who}"]`);if(who==='assassin')await click('starter',`[data-starter="${starter}"]`);await click('start');await page.evaluate(()=>setMotionMode('fast'));const route=[],events=[],arrivals=[],battles=[];
  for(let step=0;step<160;step++){
   const s=await state(),p=s.player;if(['victory','defeat'].includes(s.screen))break;
   if(s.screen==='arrival'){arrivals.push(s.journey.regionIndex);await click('arrival-enter');continue;}
   if(s.screen==='map'){const priority={rest:p.hp<45?120:40,fox:65,event:80,shop:60,fight:35,elite:15,boss:5};const nodes=s.map.flat().filter(n=>s.availableNodes.includes(n.id));nodes.sort((a,b)=>(b.storyId==='liu_first'?200:priority[b.type])-(a.storyId==='liu_first'?200:priority[a.type]));const n=nodes[0];assert.ok(n);route.push({floor:s.floor,type:n.type,id:n.id});await click('node',`[data-node="${n.id}"]`);continue;}
   if(s.screen==='battle'){battles.push({floor:s.floor,id:s.battle.enemy.id,power:p.power});await autoBattle();continue;}
   if(s.screen==='reward'){await reward();continue;}
   if(s.screen==='rest'){await click('rest','[data-heal="true"]');continue;}
   if(s.screen==='fox'){await click('fox',`[data-sign="${!p.relics.includes('fox')}"]`);continue;}
   if(s.screen==='shop'){if(p.gold>=35)await click('buy','[data-index="0"]');await click('leave-shop');continue;}
   if(s.screen==='threshold'){await click('threshold-leave');continue;}
   if(s.screen==='event'){if(s.event.resolved){await click('event-leave');continue;}const options=s.event.choices.map((choice,index)=>({choice,index})).filter(x=>!x.choice.disabled);const score=x=>(x.choice.heal||0)*(p.hp<38?3:.7)+(x.choice.relic?25:0)+(x.choice.cardIds?.length||0)*8+(x.choice.goldGain||0)/5-(x.choice.hpCost||0)*2-(x.choice.maxHpCost||0)*2-(x.choice.goldCost||0)/7+(x.choice.guard||0)*.6;options.sort((a,b)=>score(b)-score(a));const chosen=options[0];assert.ok(chosen);events.push({floor:s.floor,id:s.event.id,choice:chosen.index});await click('event-choice',`[data-index="${chosen.index}"]`);continue;}
   throw Error('Unexpected screen '+s.screen);
  }
  const s=await state();attempts.push({result:s.screen,hp:s.player.hp,maxHp:s.player.maxHp,level:s.player.level,power:s.player.power,history:s.history.length,route,events,arrivals,battles});if(s.screen==='victory')return attempts;
 }throw Error('No natural victory: '+JSON.stringify(attempts));
}
(async()=>{
 const source=fs.readFileSync(target,'utf8');report.sha256=hash(source);report.inputs=Object.fromEntries(['dev/engine.js','dev/expansion.js','dev/ui.js','dev/shell.html','dev/scene.js','dev/art.js'].filter(f=>fs.existsSync(path.join(__dirname,'..',f))).map(f=>[f,hash(fs.readFileSync(path.join(__dirname,'..',f)))]));
 const root=path.dirname(target),mime={'.html':'text/html;charset=utf-8','.webp':'image/webp','.js':'text/javascript;charset=utf-8'};
 server=http.createServer((req,res)=>{let file;try{file=path.resolve(root,'.'+decodeURIComponent(new URL(req.url,'http://local').pathname));}catch{res.writeHead(400).end();return;}if(!file.startsWith(root+path.sep)){res.writeHead(403).end();return;}fs.readFile(file,(e,b)=>{if(e){res.writeHead(404).end();return;}res.writeHead(200,{'Content-Type':mime[path.extname(file)]||'application/octet-stream','Cache-Control':'no-store'}).end(b);});});await new Promise(r=>server.listen(0,'127.0.0.1',r));origin='http://127.0.0.1:'+server.address().port;
 try{
  browser=await chromium.launch({executablePath:'/usr/bin/chromium',headless:true,args:['--no-sandbox']});page=await browser.newPage({viewport:{width:1440,height:1060}});watch(page);await page.goto(origin+'/'+path.basename(target),{waitUntil:'load'});await page.waitForFunction(()=>window.game&&window.NightPact);await page.evaluate(()=>setMotionMode('fast'));

  await test('隐藏职业初始锁定，不能借开局按钮绕过解锁',async()=>{const profile=await page.evaluate(()=>game.getProfile());assert.ok(!profile.unlocks.includes('feiye'));const button=page.locator('[data-action="character"][data-character="sovereign"]');assert.equal(await button.count(),1);assert.equal(await button.isDisabled(),true);const before=await state();assert.equal(await page.evaluate(()=>game.newRun('sovereign')),false);assert.deepEqual(await state(),before);await screenshot('locked-title');});

  await test('fixture 二十套路线模板、四十个以上节点与当前地域的二维背景点选',async()=>{
    report.templates=await page.evaluate(()=>NightPact.ROUTE_TEMPLATES.map((template,index)=>{const g=NightPact.createGame({routeTemplate:index});g.newRun('sword');return{id:template.id,widths:template.widths,nodeCount:g.state.map.flat().length,chosen:g.state.mapTemplateId,types:g.state.map.flat().map(n=>n.type)};}));
    assert.ok(report.templates.length>=20);assert.equal(new Set(report.templates.map(x=>JSON.stringify(x.widths))).size,report.templates.length);for(const row of report.templates){assert.ok(row.nodeCount>=40);assert.equal(row.chosen,row.id);}
    await newRun();await enterRegion();const s=await state();assert.ok(s.map.flat().length>=40);assert.equal(await page.evaluate(()=>typeof NightScene),'undefined');assert.equal(await page.evaluate(()=>typeof NightPuppet),'undefined');assert.equal(await page.locator('#app canvas,[data-scene],.character-model,.model-card').count(),0);
    const visible=await page.locator('.painted-map .map-node[data-node]').evaluateAll(xs=>xs.map(x=>x.dataset.node));assert.equal(visible.length,s.map.slice(0,4).flat().length);assert.ok(visible.every(id=>s.map.slice(0,4).flat().some(n=>n.id===id)));assert.equal(await page.locator('[data-node^="f5-"]').count(),0);
    const image=page.locator('.painted-background[data-painted-region] .painted-region img').first();const decoded=await image.evaluate(async img=>{await img.decode();return{src:img.getAttribute('src'),width:img.naturalWidth};});assert.ok(decoded.width>100);report.paintedMap={template:s.mapTemplateId,totalNodes:s.map.flat().length,currentNodes:visible.length,background:decoded};
    const id=s.availableNodes[0];await page.locator(`.painted-map .map-node[data-node="${id}"]`).click({timeout:7000});assert.equal((await state()).screen,'battle');await screenshot('painted-first-battle');
  });

  await test('fixture 人物只由言行呈现：事件无人物介绍、阵营立场和提前夺宝标签',async()=>{for(const id of ['liu_first','ji_first','wen_first']){await eventFixture(id);assert.equal(await page.locator('.encounter-person').count(),0);const text=await page.locator('#app').innerText();assert.ok(!/成年[男女]|待人谦和|不肯放下的罪证|夺宝剑客|反目成仇|greedy|grateful/.test(text),text);assert.ok(!text.includes(id.toUpperCase()));const alts=await page.locator('#app img').evaluateAll(xs=>xs.map(x=>x.alt).join(' '));assert.ok(!/夺宝|叛徒|坏人|恶人/.test(alts));}report.noIntroductions=true;await screenshot('unnamed-intentions');});

  await test('fixture 地域负面效果实际结算，并在当前地域展示规则',async()=>{report.environments=[];await battleFixture(1,{enemy:'paper'});let s=await state();assert.equal(s.player.hp,59);assert.ok(await page.locator('[data-environment]').count());report.environments.push({region:0,hp:s.player.hp,energy:s.battle.energy,environment:await page.evaluate(()=>game.getEnvironment())});await battleFixture(5,{enemy:'paper'});s=await state();assert.equal(s.battle.energy,2);report.environments.push({region:1,hp:s.player.hp,energy:s.battle.energy,environment:await page.evaluate(()=>game.getEnvironment())});await battleFixture(9,{enemy:'paper'});s=await state();const initial=s.player.hp;for(let i=0;i<2;i++){await page.evaluate(()=>{game.state.battle.block=100;renderGame();});await endTurn();}s=await state();assert.equal(s.battle.turn,3);assert.equal(s.player.hp,initial-1);report.environments.push({region:2,turn:s.battle.turn,hp:s.player.hp,environment:await page.evaluate(()=>game.getEnvironment())});await screenshot('environment-core');});

  await test('fixture 神剑可装备，等级不足按可见固定次序反噬而非暗改随机结果',async()=>{await newRun();await page.evaluate(()=>{game.state.player.weaponInventory=['training','divine'];game.state.player.level=1;renderGame();});await click('equipment');await click('equip-weapon','[data-id="divine"]');await click('close');assert.equal((await state()).player.equippedWeapon,'divine');await enterRegion();await click('node','.route-choice');let s=await state();assert.equal(s.battle.energy,2);assert.ok(await page.locator('#weapon-omen').count());const status=await page.evaluate(()=>game.getWeaponStatus());const hp=s.player.hp;await page.evaluate(()=>{game.state.battle.enemy.id='paper';game.state.battle.enemy.name='纸人';game.state.battle.enemy.hp=999;game.state.battle.enemy.maxHp=999;game.state.battle.enemy.intentIndex=0;game.state.battle.block=100;renderGame();});await endTurn();s=await state();assert.equal(s.player.hp,hp-3);await page.evaluate(()=>{game.state.battle.block=100;renderGame();});await endTurn();s=await state();assert.equal(s.battle.turn,3);assert.equal(s.battle.enemy.block,6);assert.equal(await page.evaluate(()=>game.equipWeapon('training')),false);report.divine={status,turn3:s.battle,player:s.player};await screenshot('divine-rebellion');});

  await test('fixture 商店购剑真实扣钱且仅能购买一次，余额不足的商品置灰',async()=>{
    await newRun();await enterRegion();await page.evaluate(()=>{const n=game.getAvailableNodes()[0];n.type='shop';delete n.storyId;game.state.player.gold=100;game.enterNode(n.id);renderGame();});
    let s=await state();const index=s.shop.weapons.findIndex(w=>w.id==='divine');assert.ok(index>=0);const price=s.shop.weapons[index].price;await click('buy-weapon',`[data-index="${index}"]`);s=await state();assert.equal(s.player.gold,100-price);assert.ok(s.player.weaponInventory.includes('divine'));assert.equal(await page.evaluate(index=>game.buyWeapon(index),index),false);assert.equal((await state()).player.gold,100-price);
    for(let i=0;i<s.shop.weapons.length;i++){const item=s.shop.weapons[i];if(!item.bought&&item.price>s.player.gold)assert.equal(await page.locator(`[data-action="buy-weapon"][data-index="${i}"]`).isDisabled(),true);}report.weaponPurchase={price,remaining:s.player.gold,inventory:s.player.weaponInventory};await click('leave-shop');
  });

  await test('fixture 正常胜利增加修为，达到要求后神剑不再失控',async()=>{await battleFixture(1,{player:{xp:5,level:3,weaponInventory:['training','divine'],equippedWeapon:'divine'}});const before=await state();await fixtureKill();let s=await state();assert.equal(s.screen,'reward');assert.ok(s.player.xp>before.player.xp);assert.ok(s.player.level>=4);await reward();await page.evaluate(()=>{const n=game.getAvailableNodes()[0];n.type='fight';delete n.storyId;game.enterNode(n.id);renderGame();});s=await state();assert.equal(s.battle.energy,3);report.suppression={level:s.player.level,status:await page.evaluate(()=>game.getWeaponStatus())};});

  await test('fixture 三条隐线只能由真实事件选择收集，重复点击不重复支付',async()=>{report.clues=[];await newRun();await enterRegion();for(const [floor,id,flag]of [[3,'moon_trace','bellEcho'],[6,'sealed_name','ritualName'],[10,'moon_vow','emptyVow']]){await skipToFloor(floor);await enterRegion();const s=await state(),node=s.map.flat().find(n=>s.availableNodes.includes(n.id)&&n.storyId===id);assert.ok(node,'Guaranteed reachable '+id);await click('node',`[data-node="${node.id}"]`);const e=(await state()).event;const index=e.choices.findIndex(c=>!c.disabled&&(c.flags?.[flag]||c.hiddenFlags?.[flag]));assert.ok(index>=0,'clue choice '+flag);const after=await chooseOnce(index);assert.equal(after.journey.flags[flag],true);report.clues.push({id,flag,choice:index,received:after.event.received});await click('event-leave');}assert.equal((await state()).floor,11);});

  await test('fixture 缺少隐线条件无法见到隐藏战，普通结局仍可完成',async()=>{await battleFixture(12,{kind:'boss'});assert.equal((await state()).battle.enemy.id,'snake');await fixtureKill();let s=await state();assert.ok(['victory','threshold'].includes(s.screen));assert.equal(await page.evaluate(()=>game.startHiddenBoss()),false);if(s.screen==='threshold')await click('threshold-leave');assert.equal((await state()).screen,'victory');assert.ok(!(await page.evaluate(()=>game.getProfile())).unlocks.includes('feiye'));});

  await test('fixture 收齐隐线并击败隐藏Boss后真实解锁，刷新仅保留职业解锁',async()=>{await battleFixture(12,{kind:'boss'});await page.evaluate(()=>{Object.assign(game.state.journey.flags,{bellEcho:true,ritualName:true,emptyVow:true});});await fixtureKill();assert.equal((await state()).screen,'threshold');await screenshot('hidden-threshold');await click('hidden-enter');let s=await state();assert.equal(s.screen,'battle');assert.equal(s.battle.enemy.id,'feiye');assert.equal(s.battle.enemy.maxHp,120);assert.equal(await page.evaluate(()=>game.startHiddenBoss()),false);await screenshot('hidden-boss');await fixtureKill();s=await state();assert.equal(s.screen,'victory');assert.ok((await page.evaluate(()=>game.getProfile())).unlocks.includes('feiye'));await page.reload({waitUntil:'load'});await page.waitForFunction(()=>window.game);await page.evaluate(()=>setMotionMode('fast'));assert.equal((await state()).screen,'title');assert.equal(await page.locator('[data-action="character"][data-character="sovereign"]').isDisabled(),false);assert.ok((await page.evaluate(()=>game.getProfile())).unlocks.includes('feiye'));await click('profile');assert.ok((await page.locator('#profile-code').inputValue()).includes('feiye'));await click('close');report.unlock={persisted:true,profile:await page.evaluate(()=>game.getProfile())};await screenshot('unlocked-title');});

  await test('fixture 绯夜专属三境故事与分身、旧部、心魔真实战斗，胜后力量逐次提升',async()=>{await newRun('sovereign');await enterRegion();let expectedPower=0;report.sovereignQuest=[];for(const [floor,id]of [[2,'sovereign_wake'],[4,'feiye_echo'],[5,'sovereign_recall'],[7,'retainer'],[9,'sovereign_memory'],[10,'heart'],[12,'snake_ascended']]){await skipToFloor(floor);await enterRegion();const s=await state(),n=s.map.flat().find(n=>s.availableNodes.includes(n.id));await click('node',`[data-node="${n.id}"]`);let opened=await state();if(opened.screen==='event'){assert.equal(opened.event.id,id);assert.ok(!/柳照青|季临川|闻人烛/.test(opened.event.story.join('')));const index=opened.event.choices.findIndex(c=>!c.disabled);await chooseOnce(index);await click('event-leave');report.sovereignQuest.push({floor,event:id});}else{assert.equal(opened.screen,'battle');assert.equal(opened.battle.enemy.id,id);await fixtureKill();opened=await state();if(floor<12){expectedPower++;assert.equal(opened.player.power,expectedPower);await reward();}else assert.equal(opened.screen,'victory');report.sovereignQuest.push({floor,enemy:id,power:opened.player.power});}}assert.equal((await state()).player.power,3);await screenshot('sovereign-exclusive-ending');});

  await test('新增职业技能、武器、人物及特殊场景资源实际解码',async()=>{report.art=await page.evaluate(async()=>{const rows=[...Object.entries(NightAssets.cards).filter(([id])=>id.startsWith('F')).map(([id,src])=>['card:'+id,src]),...Object.entries(NightAssets.weapons||{}).map(([id,src])=>['weapon:'+id,src]),...Object.entries(NightAssets.puppet.feiye||{}).map(([id,src])=>['feiye:'+id,src]),...['feiye','feiye_echo','retainer','heart','snake_ascended'].map(id=>['portrait:'+id,NightAssets.portraits[id]])];const out=[];for(const[id,src]of rows){if(!src)throw Error('Missing '+id);const img=new Image();img.src=src;await img.decode();const c=document.createElement('canvas');c.width=32;c.height=48;c.getContext('2d').drawImage(img,0,0,32,48);const data=c.getContext('2d').getImageData(0,0,32,48).data;let f=0;for(const n of data)f=(Math.imul(f,31)+n)|0;out.push({id,width:img.naturalWidth,height:img.naturalHeight,fingerprint:f});}return out;});assert.equal(report.art.filter(x=>x.id.startsWith('card:')).length,12);assert.equal(report.art.filter(x=>x.id.startsWith('weapon:')).length,4);assert.equal(new Set(report.art.filter(x=>x.id.startsWith('card:')).map(x=>x.fingerprint)).size,12);assert.equal(new Set(report.art.filter(x=>x.id.startsWith('feiye:')).map(x=>x.fingerprint)).size,3);
    await newRun('sovereign');await enterRegion();await click('node','.current');report.feiyeDamageStates=[];for(const [hp,stage]of [[31,'normal'],[30,'wounded'],[15,'critical']]){await page.evaluate(hp=>{game.state.player.hp=hp;renderGame();},hp);const visual=await page.locator('.player-combatant .portrait[data-portrait="feiye"]').evaluate(el=>({stage:el.dataset.damageStage,src:el.querySelector(':scope > img')?.getAttribute('src')}));assert.equal(visual.stage,stage);const expected=await page.evaluate(stage=>NightAssets.puppet.feiye[stage],stage);assert.equal(visual.src,expected);report.feiyeDamageStates.push({hp,...visual});}await screenshot('feiye-critical');
  });

  await test('事件画卡随职业切换：两套各二十一张独立画卡与当前角色一致',async()=>{
    report.roleArt=await page.evaluate(async()=>{const result={};for(const role of ['sword','sovereign']){const rows=Object.entries(NightAssets.eventsByCharacter[role]);const out=[];for(const[id,src]of rows){const img=new Image();img.src=src;await img.decode();out.push({id,src,width:img.naturalWidth,height:img.naturalHeight});}result[role]=out;}return result;});assert.equal(report.roleArt.sword.length,21);assert.equal(report.roleArt.sovereign.length,21);
    report.eventArtSelection=[];for(const starter of ['mark','sword','sovereign']){await eventFixture('well',{starter});const s=await state(),src=await page.locator('[data-event-art="well"] img').getAttribute('src'),expected=await page.evaluate(()=>NightAssets.eventsByCharacter?.[game.state.character]?.well||NightAssets.events.well);assert.equal(src,expected);report.eventArtSelection.push({character:s.character,src});}assert.equal(new Set(report.eventArtSelection.map(x=>x.src)).size,3);await screenshot('sovereign-event-art');
  });

  await test('三职业真实DOM十二段通关并重开，完整流程不修改本局资源',async()=>{report.naturalRuns={};for(const starter of ['sword','mark','sovereign']){report.naturalRuns[starter]=await naturalRun(starter);let s=await state();assert.equal(s.screen,'victory');assert.equal(s.history.length,12);assert.deepEqual(report.naturalRuns[starter].at(-1).arrivals,[0,1,2]);if(starter==='sovereign'){const ids=report.naturalRuns[starter].at(-1).battles.map(b=>b.id);for(const id of ['feiye_echo','retainer','heart','snake_ascended'])assert.ok(ids.includes(id),id);assert.equal(s.player.power,3);}await screenshot(starter+'-natural-victory');await click('start');s=await state();assert.equal(s.screen,'arrival');assert.equal(s.player.hp,60);assert.equal(s.player.gold,60);assert.equal(s.player.deck.length,10);assert.equal(s.player.level,1);assert.equal(s.player.power,0);assert.equal(s.history.length,0);assert.equal(s.journey.journal.length,0);}});

  await test('素材缺失仍有二维替代图，完整单文件解锁凭证可导入且运行不联网',async()=>{const html=fs.readFileSync(inlineTarget,'utf8'),p=await browser.newPage({viewport:{width:1440,height:1060}}),requests=[];watch(p);p.on('request',r=>{if(/^https?:/.test(r.url()))requests.push(r.url());});try{await p.setContent(html,{waitUntil:'load'});await p.waitForFunction(()=>window.game);await p.locator('[data-action="profile"]').click();await p.locator('#profile-code').fill(JSON.stringify(report.unlock.profile));await p.locator('[data-action="profile-import"]').click();await p.locator('[data-action="close"]').click();await p.locator('[data-action="character"][data-character="sovereign"]').click();await p.locator('[data-action="start"]').click();await p.locator('[data-action="arrival-enter"]').click();await p.locator('.current-routes [data-action="node"]').first().click();assert.equal(await p.evaluate(()=>game.state.character),'sovereign');assert.equal(await p.evaluate(()=>game.state.screen),'battle');const img=p.locator('.portrait[data-portrait="feiye"] img').first();const width=await img.evaluate(async el=>{await el.decode();return el.naturalWidth;});assert.ok(width>100);assert.deepEqual(requests,[]);report.inline={bytes:Buffer.byteLength(html),sha256:hash(html),requests};}finally{await p.close();}
   const fallback=await browser.newPage();watch(fallback);await fallback.route('**/assets/**',r=>{report.expectedMissingRequests.push(r.request().url());return r.abort();});try{await fallback.goto(origin+'/'+path.basename(target),{waitUntil:'load'});await fallback.evaluate(profile=>{game.importProfile(profile);renderGame();},report.unlock.profile);await fallback.locator('[data-action="character"][data-character="sovereign"]').click();await fallback.locator('[data-action="start"]').click();await fallback.locator('[data-action="arrival-enter"]').click();await fallback.locator('.current-routes [data-action="node"]').first().click();assert.equal(await fallback.evaluate(()=>game.state.screen),'battle');assert.ok(await fallback.locator('.portrait[data-portrait="feiye"] svg').count());assert.equal(await fallback.evaluate(()=>typeof NightScene),'undefined');assert.equal(await fallback.locator('#app canvas,[data-scene]').count(),0);report.fallback=true;}finally{await fallback.close();}});

  await test('当前构建未捕获JavaScript异常和运行时外网请求为零',async()=>{assert.deepEqual(report.errors,[]);assert.deepEqual(report.externalRequests,[]);});report.browser=await browser.version();
 }finally{if(browser)await browser.close();if(server)await new Promise(r=>server.close(r));report.passed=report.results.filter(x=>x.ok).length;report.failed=report.results.length-report.passed;fs.writeFileSync(path.join(__dirname,process.env.QA_REPORT||'v7-results.json'),JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify({passed:report.passed,failed:report.failed,errors:report.errors,externalRequests:report.externalRequests,sha256:report.sha256},null,2));}if(report.failed)process.exitCode=1;
})().catch(e=>{console.error(e.stack);process.exitCode=1;});
